Q: Calculate Exponential Moving Average using Pandas DataFrame A: <pre><code>import pandas as pd
import requests
import time

# --- ১. ইন্ডিকেটর হিসাব করার ফাংশন ---
def calculate_indicators(df):
    # Exponential Moving Average (EMA)
    df['EMA_9'] = df['close'].ewm(span=9, adjust=False).mean()
    df['EMA_21'] = df['close'].ewm(span=21, adjust=False).mean()

    # Relative Strength Index (RSI)
    delta = df['close'].diff()
    gain = (delta.where(delta &gt; 0, 0)).rolling(window=14).mean()
    loss = (-delta.where(delta &lt; 0, 0)).rolling(window=14).mean()
    rs = gain / loss
    df['RSI'] = 100 - (100 / (1 + rs))

    return df

# --- ২. সিগন্যাল বের করার লজিক ---
def generate_signal(df):
    latest_row = df.iloc[-1]
    prev_row = df.iloc[-2]

    # Buy / Call Signal: RSI &lt; 30 (Oversold) এবং EMA Cross
    if latest_row['RSI'] &lt; 35 and latest_row['EMA_9'] &gt; latest_row['EMA_21']:
        return &quot;CALL (BUY) 📈 - Market Oversold &amp; Bullish Trend&quot;

    # Sell / Put Signal: RSI &gt; 70 (Overbought) এবং EMA Cross
    elif latest_row['RSI'] &gt; 65 and latest_row['EMA_9'] &lt; latest_row['EMA_21']:
        return &quot;PUT (SELL) 📉 - Market Overbought &amp; Bearish Trend&quot;

    return &quot;NEUTRAL ⏳ - No Clear Signal&quot;

# --- ৩. টেলিগ্রামে মেসেজ পাঠানোর ফাংশন ---
def send_telegram_msg(bot_token, chat_id, message):
    url = f&quot;https://api.telegram.org/bot{bot_token}/sendMessage&quot;
    payload = {&quot;chat_id&quot;: chat_id, &quot;text&quot;: message}
    requests.post(url, json=payload)

# নমুনা ডাটা দিয়ে টেস্ট করা
data = {
    'close': [1.0850, 1.0852, 1.0848, 1.0845, 1.0840, 1.0838, 1.0835, 1.0832, 1.0830, 1.0833, 1.0837, 1.0842, 1.0846, 1.0850, 1.0855]
}
df = pd.DataFrame(data)
df = calculate_indicators(df)
signal = generate_signal(df)

print(f&quot;Current Market Signal: {signal}&quot;)
</code></pre>
